; Learned from capture.json: pulse width, 25 bits per frame
; Generated by escgen from protocols/learned_on_chip.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: inferred by esclearn from capture.json (4 frames)
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ H0, CLK_KHZ * 7250 // 25000
.equ H1, CLK_KHZ * 23000 // 25000
.equ T, CLK_KHZ * 31500 // 25000
.equ GAP, CLK_KHZ * 229950 // 25000
.default PIN_OUT, 0
.equ P_OUT, 1 << PIN_OUT

.own  PIN_OUT, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_OUT, 0, P_OUT             ; idle levels
    ADDT  1
packet:
    POP   r0                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    LDSH  r0                          ; 25 bits, LSB first
    LDLC  25
bit1:
    EMIT  P_OUT, P_OUT, P_OUT
    ADDT  H0
    EMITX P_OUT, LSB, P_OUT           ; data bit
    ADDT  H1 - H0
    EMIT  P_OUT, 0, P_OUT
    ADDT  T - H1
    DJNZ  bit1
    ADDT  GAP - 64                    ; gap: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet
